gD2(){return"\uc88b\uc74c"},
gD0(){return"\ud65c\ub825 \ub118\uce68"},
tK(a,b){return a+"\uc5d0\uc11c \uc870\uc815\ub428: "+b},
go8(){return", "},
gyb(){return"\uc624\ub298 \uc5d0\ub108\uc9c0 \ubd80\uc871"},
gya(){return"\uc624\ub298 \uc5d0\ub108\uc9c0 \ucda9\ubd84"},
gy9(){return"\ub204\uc801 \ud53c\ub85c"},
gy8(){return"\ud734\uc2dd \ud6c4 \ubcf5\uadc0"},
gyc(){return"\ucd5c\uadfc \uacb0\uacfc \uae30\uc900"},
gyd(){return"\uacc4\ud68d\ubcf4\ub2e4 \uc798\ud558\uace0 \uc788\uc74c"},
