gA0(){return"\uc810\ud504"},
gAK(){return"\uc810\ud504 1000\uac1c\uae4c\uc9c0 \uac00\ub294 \uae38"},
gAj(){return"\uc9c0\uae08\uc758 \ucd5c\uace0 \uae30\ub85d\uc5d0\uc11c \uc5f0\uc18d \uc810\ud504 1000\uac1c\uae4c\uc9c0 \uc774\ub04c\uc5b4 \uc904 \ub9de\ucda4 \uc77c\uc77c \ud50c\ub79c\uc744 \ub9cc\ub4e4\uc5b4\uc694. \uc904\ub118\uae30\uac00 \uc788\uc5b4\ub3c4 \uc5c6\uc5b4\ub3c4 \uc88b\uc544\uc694. 1\uc81c\uacf1\ubbf8\ud130 \uacf5\uac04\uacfc \ud558\ub8e8 \uba87 \ubd84\uc774\uba74 \ucda9\ubd84\ud574\uc694."},
gAs(){return"\uc885\uc544\ub9ac, \ubc1c\ubaa9, \uadf8\ub9ac\uace0 \uc2ec\uc7a5. \uc810\ud504\ud560 \ub54c\ub9c8\ub2e4 \uc885\uc544\ub9ac, \uc544\ud0ac\ub808\uc2a4\uac74, \ubc1c\ubc14\ub2e5\uc774 \ub2e8\ub828\ub418\uace0, \uc5f0\uc18d 1000\uac1c\ub294 8~10\ubd84\uc758 \uc27c \uc5c6\ub294 \uc720\uc0b0\uc18c \uc6b4\ub3d9\uc774\uc5d0\uc694."},
gAa(){return"\uc9c0\uad6c\ub825, \ud611\uc751\ub825, \ub2e4\ub9ac\uc758 \ud0c4\ub825\uc774 \uc88b\uc544\uc9c0\uace0 \uc801\ub2f9\ud55c \ucda9\uaca9\uc774 \ubf08\uc640 \ud798\uc904\uc744 \ud2bc\ud2bc\ud558\uac8c \ud574\uc694. \uadf8\ub798\uc11c \ub2e4\ub978 \uc6b4\ub3d9\ubcf4\ub2e4 \ub354 \uc138\uc2ec\ud55c \uad00\ub9ac\uac00 \ud544\uc694\ud558\uace0, \ud50c\ub79c\ub3c4 \ub354 \ucc9c\ucc9c\ud788 \uc62c\ub77c\uac00\uc694."},
gAB(){return"\ud558\ub098\uc529\uc774\uba74 \uc810\ud504 1000\uac1c\ub294 \uc26c\uc6cc\uc694. \ud558\uc9c0\ub9cc \uba48\ucd94\uc9c0 \uc54a\uace0 \uc5f0\uc18d\uc73c\ub85c \ud558\uba74 \uc9d1\uc5d0\uc11c \ud560 \uc218 \uc788\ub294 \uac00\uc7a5 \ud798\ub4e0 \uc9c0\uad6c\ub825 \ub3c4\uc804 \uc911 \ud558\ub098\uc608\uc694. \ubd84\ub2f9 100~120\uac1c \uc18d\ub3c4\ub85c 8~10\ubd84. \ud798\uc904\uc740 \uadfc\uc721\ubcf4\ub2e4 \ub290\ub9ac\uac8c \uc801\uc751\ud558\ub2c8 \ud50c\ub79c\uc740 \ucc28\ubd84\ud788 \uc62c\ub77c\uac00\uace0, 3\uc8fc\ub9c8\ub2e4 \ud55c \uc8fc\ub294 \uac00\ubcbc\uc6b4 \uc8fc\uc608\uc694."},
gAS(){return"\ud734\ub300\ud3f0\uc758 \uac00\uc18d\ub3c4 \uc13c\uc11c\ub97c \uc0ac\uc6a9\ud574\uc694. \ubab8\uc5d0 \ub531 \ub9de\ub294 \uc8fc\uba38\ub2c8\ub098 \ud5c8\ub9ac \uac00\ubc29\uc5d0 \ub123\uace0, \uc190\uc5d0 \ub4e4\uc9c0 \ub9c8\uc138\uc694. \uacf5\uc911\uc5d0\uc11c\ub294 \ud734\ub300\ud3f0\uc774 \ud568\uaed8 \ub5a8\uc5b4\uc9c0\uace0, \ucc29\uc9c0\ud560 \ub54c \ucda9\uaca9\uc744 \ubc1b\uc544\uc694. \uccb4\uacf5 \ub4a4\uc5d0 \ucc29\uc9c0\uac00 \uc624\uba74 \uc810\ud504 1\uac1c\ub85c \uc138\uc694. \uac77\uac70\ub098 \ud734\ub300\ud3f0\uc744 \ud754\ub4dc\ub294 \uac74 \uc138\uc9c0 \uc54a\uc544\uc694."},
gzS(){return"\ud734\ub300\ud3f0\uc740 \ub531 \ub9de\ub294 \uc8fc\uba38\ub2c8\ub098 \ud5c8\ub9ac \uac00\ubc29\uc5d0."},
gDH(){return"\ubb34\ub98e\uc744 \uc0b4\uc9dd \uad7d\ud788\uace0 \ubc1c \uc55e\ucabd\uc73c\ub85c \ucc29\uc9c0\ud558\uc138\uc694. \ubc1c\ub4a4\uafc8\uce58\ub85c \ucc29\uc9c0\ud558\uc9c0 \ub9c8\uc138\uc694."},
gDI(){return"\ub0ae\uac8c \ub6f0\uc138\uc694. \uc904\uc774 \uc9c0\ub098\uac00\ub824\uba74 2~3\uc13c\ud2f0\ubbf8\ud130\uba74 \ucda9\ubd84\ud574\uc694. \ub354 \ub192\uc774 \ub6f0\uba74 \ud798\ub9cc \ub4e4\uace0 \ubc1c\ubaa9\uc5d0 \ubb34\ub9ac\uac00 \uac00\uc694."},
gDJ(){return"\ub098\ubb34, \uace0\ubb34, \ub9e4\ud2b8 \uc704\uc5d0\uc11c \ucfe0\uc158 \uc788\ub294 \uc2e0\ubc1c\uc744 \uc2e0\uace0 \ub6f0\uc138\uc694. \ucf58\ud06c\ub9ac\ud2b8\uc640 \uc544\uc2a4\ud314\ud2b8\ub294 \ud53c\ud558\uc138\uc694."},
gDK(){return"\uc904\uc740 \uc190\ubaa9\uc73c\ub85c \ub3cc\ub9ac\uace0 \ud314\uafc8\uce58\ub294 \ubab8\uc5d0 \ubd99\uc774\uc138\uc694. \uc904\uc774 \uc5c6\ub098\uc694? \ub3cc\ub9ac\ub294 \ub3d9\uc791\uc744 \ud749\ub0b4 \ub0b4\uba70 \ub9ac\ub4ec\uc744 \uc720\uc9c0\ud558\uc138\uc694."},
gDL(){return"1\ubd84\uac04 \uac00\ubccd\uac8c \ud1b5\ud1b5 \ub6f0\uace0 \ubc1c\ubaa9\uc744 \ub3cc\ub824 \uc6cc\ubc0d\uc5c5\ud558\uc138\uc694. \ub05d\ub098\uba74 \uc885\uc544\ub9ac\ub97c \uc2a4\ud2b8\ub808\uce6d\ud558\uc138\uc694."},
gDM(){return"\ub2e4\uc74c \ub0a0 \uc815\uac15\uc774\ub098 \ubc1c\ub4a4\uafc8\uce58\uac00 \uc544\ud504\uba74 \ud558\ub8e8 \ub354 \uc26c\uc138\uc694. \ud798\uc904\uc740 \uadfc\uc721\ubcf4\ub2e4 \ud68c\ubcf5\uc774 \ub290\ub824\uc694."},
gBF(){return"\uc810\ud504\uac00 \uc788\ub294 \uc6b4\ub3d9\uc740 \ucc29\uc9c0\ud560 \ub54c\ub9c8\ub2e4 \uc885\uc544\ub9ac, \ud798\uc904, \uc815\uac15\uc774\uc5d0 \uccb4\uc911\uc758 2~3\ubc30 \ubd80\ud558\uac00 \uac78\ub9ac\uace0, \ud798\uc904\uc740 \uadfc\uc721\ubcf4\ub2e4 \ub290\ub9ac\uac8c \uc801\uc751\ud574\uc694. \uadf8\ub798\uc11c \uc5ec\uae30\uc11c\ub294 \ubd80\ud558\uac00 \uc8fc\ub2f9 \ucd5c\ub300 10%\uae4c\uc9c0\ub9cc \ub298\uace0, 3\uc8fc\ub9c8\ub2e4 \ud55c \uc8fc\ub294 \uac00\ubcbc\uc6b4 \uc8fc(60%)\uc774\uba70, \uac01 \uc138\uc158\uc740 \uc9e7\uc740 \uc6cc\ubc0d\uc5c5\uacfc \uadf8\ub0a0\uc758 \uc22b\uc790\ub85c \uad6c\uc131\ub418\uace0, \ub098\uc774\xb7\uccb4\uc911\xb7\ud65c\ub3d9 \uc218\uc900\uc774 \ub354 \ud06c\uac8c \ubc18\uc601\ub3fc\uc694."},
gzH(){return"Road To 100 Burpees"},
gzZ(){return"\ubc84\ud53c"},
gAI(){return"\ubc84\ud53c 100\uac1c\uae4c\uc9c0 \uac00\ub294 \uae38"},
gAh(){return"\uc9c0\uae08\uc758 \ucd5c\uace0 \uae30\ub85d\uc5d0\uc11c \uc5f0\uc18d \ubc84\ud53c 100\uac1c\uae4c\uc9c0 \uc774\ub04c\uc5b4 \uc904 \ub9de\ucda4 \uc77c\uc77c \ud50c\ub79c\uc744 \ub9cc\ub4e4\uc5b4\uc694. \uae30\uad6c \uc5c6\uc774, 2\uc81c\uacf1\ubbf8\ud130 \uacf5\uac04\uacfc \ud558\ub8e8 \uba87 \ubd84\uc774\uba74 \ucda9\ubd84\ud574\uc694."},
gAq(){return"\uc628\ubab8\uc744 \ud55c \ubc88\uc5d0. \uc2a4\ucffc\ud2b8\uc640 \uc810\ud504\ub85c \ub2e4\ub9ac, \ud50c\ub7ad\ud06c\ub85c \uc5b4\uae68\xb7\uac00\uc2b4\xb7\ucf54\uc5b4, \uadf8\ub9ac\uace0 \ubc18\ubcf5 \uc0ac\uc774\uc5d0\ub3c4 \uc26c\uc9c0 \ubabb\ud558\ub294 \uc2ec\uc7a5."},
gA8(){return"\uae30\uad6c \uc5c6\uc774 \ud560 \uc218 \uc788\ub294 \uac00\uc7a5 \uc644\uc131\ub3c4 \ub192\uc740 \ucee8\ub514\uc154\ub2dd \uc6b4\ub3d9\uc774\uc5d0\uc694. \uadfc\ub825, \ud30c\uc6cc, \uc9c0\uad6c\ub825\uc744 \ud55c \ub3d9\uc791\uc5d0 \ub2f4\uc558\uace0, \uc774\ub9cc\ud07c \ube68\ub9ac \uc2ec\ubc15\uc218\ub97c \uc62c\ub9ac\ub294 \uc6b4\ub3d9\uc740 \ub4dc\ubb3c\uc5b4\uc694."},
gAz(){return"\ubc84\ud53c 10\uac1c\ub294 \uac70\uc758 \ub204\uad6c\ub098 \ud574\uc694. \ud558\uc9c0\ub9cc \uc5f0\uc18d 100\uac1c\ub294 \uc26c\uc9c0 \uc54a\uace0 5~8\ubd84, \ud6c8\ub828\ub41c \uc6b4\ub3d9\uc120\uc218\ub3c4 \uc2dc\ud5d8\ubc1b\ub294 \uc591\uc774\uc5d0\uc694. \ub9e4\ubc88 \uc810\ud504\ub85c \ub05d\ub098\ub2c8 \ud50c\ub79c\uc740 \ucda9\uaca9\uc774 \uc788\ub294 \uc6b4\ub3d9\ub2f5\uac8c \uc2e0\uc911\ud558\uac8c \uc62c\ub77c\uac00\uc694. \uc8fc\ub2f9 \ucd5c\ub300 10%, 3\uc8fc\ub9c8\ub2e4 \ud55c \uc8fc\ub294 \uac00\ubcbc\uc6b4 \uc8fc\uc608\uc694."},
gAR(){return"\ud734\ub300\ud3f0\uc758 \uac00\uc18d\ub3c4 \uc13c\uc11c\ub97c \uc0ac\uc6a9\ud574\uc694. \ubc14\uc9c0\uc758 \ub531 \ub9de\ub294 \uc55e\uc8fc\uba38\ub2c8\uc5d0 \ub123\uc73c\uc138\uc694. \uc11c \uc788\uc73c\uba74 \ud5c8\ubc85\uc9c0\uac00 \uc218\uc9c1\uc774\uace0 \ubc14\ub2e5\uc5d0\uc11c\ub294 \uac70\uc758 \uc218\ud3c9\uc774 \ub3fc\uc694. \ubc14\ub2e5\uae4c\uc9c0 \ub0b4\ub824\uac14\ub2e4\uac00 \ub2e4\uc2dc \uc77c\uc5b4\uc124 \ub54c\ub9c8\ub2e4 \ubc84\ud53c 1\uac1c\ub85c \uc138\uc694. \ub9c8\uc9c0\ub9c9 \uc810\ud504\ub294 \ud574\ub3c4 \uc548 \ud574\ub3c4 \ub3fc\uc694. \ud50c\ub7ad\ud06c\ub97c \uac70\uccd0\ub3c4 \ub450 \ubc88 \uc138\uc9c0 \uc54a\uc544\uc694."},
gzR(){return"\ud734\ub300\ud3f0\uc740 \ub531 \ub9de\ub294 \uc55e\uc8fc\uba38\ub2c8\uc5d0."},
gDv(){return"\ubc1c\uc744 \ub4a4\ub85c \ucc28\uae30 \uc804\uc5d0 \uc190\uc744 \uc5b4\uae68 \ubc14\ub85c \uc544\ub798 \ubc14\ub2e5\uc5d0 \uc9da\uc73c\uc138\uc694. \uc190\ubaa9\uacfc \ud5c8\ub9ac\ub97c \ubcf4\ud638\ud574\uc694."},
gDw(){return"\ud50c\ub7ad\ud06c\uc5d0\uc11c\ub294 \uc5c9\ub369\uc774\ub97c \uc77c\uc9c1\uc120\uc73c\ub85c. \ucc98\uc9c0\uc9c0\ub3c4 \ub4e4\ub9ac\uc9c0\ub3c4 \uc54a\uac8c."},
